CREATE OR REPLACE FUNCTION public.assign_signup_role_slot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  target_event public.events%rowtype;
  slot_limit integer := 1;
  candidate_slot integer;
begin
  if new.signup_role is null then
    new.role_slot := 1;
    return new;
  end if;

  select * into target_event
  from public.events event
  where event.id = new.event_id
  for update;

  if not found then
    raise exception 'Event not found.';
  end if;

  if not new.signup_role = any(target_event.open_signup_roles) then
    raise exception 'This role is not open for the selected event.';
  end if;
  if new.signup_role = 'Photographer' then
    slot_limit := target_event.photographer_slot_limit;
  elsif cardinality(target_event.open_signup_roles) = 1 then
    slot_limit := target_event.single_role_slot_limit;
  end if;

  for candidate_slot in 1..slot_limit loop
    if not exists (
      select 1
      from public.signups signup
      where signup.event_id = new.event_id
        and signup.signup_role = new.signup_role
        and signup.role_slot = candidate_slot
        and signup.confirmation_status <> 'expired'
        and signup.attendance_start is not null
        and signup.attendance_end is not null
        and tstzrange(signup.attendance_start, signup.attendance_end, '[)')
          && tstzrange(new.attendance_start, new.attendance_end, '[)')
    ) then
      new.role_slot := candidate_slot;
      return new;
    end if;
  end loop;

  raise exception 'No signup slots are available for this role during the selected time.';
end;
$function$

CREATE OR REPLACE FUNCTION public.audit_sac_membership_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  affected_member_id uuid;
  affected_team_key text;
  affected_member_name text;
  actor_member_id uuid;
  actor_name text;
  audit_action text;
begin
  if tg_op = 'DELETE' then
    affected_member_id := old.member_id;
    affected_team_key := old.team_key;
  else
    affected_member_id := new.member_id;
    affected_team_key := new.team_key;
  end if;

  if affected_team_key <> 'sac' then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if tg_op = 'UPDATE' and old.team_role is not distinct from new.team_role then
    return new;
  end if;

  select member.name into affected_member_name
  from public.members member
  where member.id = affected_member_id;

  select member.id, member.name into actor_member_id, actor_name
  from public.members member
  where lower(member.email) = lower(coalesce(auth.jwt() ->> 'email', ''))
  limit 1;

  audit_action := case tg_op
    when 'INSERT' then 'membership_added'
    when 'DELETE' then 'membership_removed'
    else 'title_changed'
  end;

  insert into public.sac_membership_audit (
    member_id,
    member_name,
    action,
    previous_title,
    new_title,
    changed_by_auth_user_id,
    changed_by_member_id,
    changed_by_name
  ) values (
    affected_member_id,
    coalesce(affected_member_name, 'Removed member'),
    audit_action,
    case when tg_op in ('UPDATE', 'DELETE') then old.team_role else null end,
    case when tg_op in ('INSERT', 'UPDATE') then new.team_role else null end,
    auth.uid(),
    actor_member_id,
    coalesce(actor_name, auth.jwt() ->> 'email', 'System')
  );

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.can_read_meeting(p_meeting_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  target_audience text;
  target_archived_at timestamptz;
begin
  if not public.can_access_media_club() then return false; end if;

  select meeting.audience, meeting.archived_at
  into target_audience, target_archived_at
  from public.meetings meeting
  where meeting.id = p_meeting_id;

  if not found then return false; end if;
  if target_archived_at is not null and not public.is_crew_operations_user() then return false; end if;
  if target_audience = 'general' then return true; end if;
  if target_audience = 'news_team' then return public.is_member_of_team('news_team'); end if;
  return target_audience = 'leadership' and public.is_crew_operations_user();
end;
$function$

